    // [WSCoop] Runs completion effects of an objective this player has without its effects (global
    // objectives are synced to everyone, but vanilla only runs their effects for the finisher).
    void WSApplyCompletionEffects(FGameplayTag ObjectiveTag)
    {
        if (!System::IsServer())
            return;
        UObjective Objective = GetObjectiveByTag(ObjectiveTag);
        if (Objective == nullptr)
            return;
        WSCoopQuests::BeginCompletion(ObjectiveTag);
        Objective.ActivateCompletionEffects(Owner, false);
        WSCoopQuests::EndCompletion();
